		/** 
		 * Tests creating a new Organization.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Organization");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Organization" );

			try {            
				Organization entity = OrganizationService.getOrganizationInstance().createOrganization( generateNewEntity() );
				thePrimaryKey = entity.getOrganizationId();
				LOGGER.info( "-- Successfully created a Organization with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Organization. 
		 */
		public Organization testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Organization" );

			Organization entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Organization with primary key" );
			msg.append( thePrimaryKey );
			
			OrganizationFetchOneSummary fetchOneSummary = new OrganizationFetchOneSummary( thePrimaryKey );

			try {
				entity = OrganizationService.getOrganizationInstance().getOrganization( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Organization " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Organization.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Organization." );

			StringBuilder msg = new StringBuilder( "Failed to update a Organization : " );        
			Organization entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Organization." );

				// for use later on...
				thePrimaryKey = entity.getOrganizationId();

				OrganizationService proxy = OrganizationService.getOrganizationInstance();            
				proxy.updateOrganization( entity );   

				LOGGER.info( "-- Successfully saved Organization - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Organization.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Organization." );

			try{
			    Organization entity = testRead(); 
				OrganizationService.getOrganizationInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Organization with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Organization with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Organizations.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Organizations:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Organization : " );        
			List<Organization> collection  = null;

			try {
				// call the static get method on the OrganizationService
				collection = OrganizationService.getOrganizationInstance().getAllOrganization();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Organization entity = null;            
					Iterator<Organization> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getOrganizationId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

